#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    Cat(string n, int f) {
        name = n;
        fish = f;
        cout << name << "：本喵出生啦" << endl;
    }

    void say() {
        cout << name << "：本喵有 " << fish << " 条小鱼干" << endl;
    }
};

int main() {
    Cat* p = new Cat("小橘", 3);
    p->say();
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;

    Cat(string n) {
        name = n;
        cout << name << "：本喵出生啦" << endl;
    }

    ~Cat() {
        cout << name << "：本喵回窝啦" << endl;
    }
};

int main() {
    Cat* p = new Cat("小橘");
    Cat* q = new Cat("狸花");
    delete p;
    delete q;
    return 0;
}

